 public static async Task<int> Exec(NpgsqlConnection c,NpgsqlTransaction? tx,string sql,CancellationToken ct,params (string,object)[] args){await using var cmd=new NpgsqlCommand(sql,c,tx);foreach(var(k,v)in args)cmd.Parameters.AddWithValue(k,v);return await cmd.ExecuteNonQueryAsync(ct);}
