  foreach(var stored in Rows(data.GetValueOrDefault(Key("conversations","global"))))if(!threads.Any(t=>Id(t)==Id(stored)))threads.Add(stored?.DeepClone());data[Key("conversations","global")]=threads;data[Key("messages","global")]=messageRows;
  var questions=await Query(c,tx,"SELECT (to_jsonb(x)||to_jsonb(p))::text FROM (SELECT 'Producto' AS tipo,producto_id AS item,cliente_id,emprendedor_id,pregunta_id FROM public.preguntarp UNION ALL SELECT 'Servicio',servicio_id,cliente_id,emprendedor_id,pregunta_id FROM public.preguntars) x JOIN public.pregunta p ON p.id=x.pregunta_id",ct);
  var ratings=await Query(c,tx,"SELECT (to_jsonb(x)||to_jsonb(c))::text FROM (SELECT 'Producto' AS tipo,producto_id AS item,cliente_id,emprendedor_id,calificacion_id,fecha FROM public.calificarp UNION ALL SELECT 'Servicio',servicio_id,cliente_id,emprendedor_id,calificacion_id,fecha FROM public.calificars) x JOIN public.calificacion c ON c.id=x.calificacion_id",ct);
  var questionsMap=questions.GroupBy(q=>CatalogId(Text(q,"tipo"),Text(q,"item"),Text(q,"emprendedor_id"))).ToDictionary(g=>g.Key,g=>g.ToArray());var ratingsMap=ratings.GroupBy(q=>CatalogId(Text(q,"tipo"),Text(q,"item"),Text(q,"emprendedor_id"))).ToDictionary(g=>g.Key,g=>g.ToArray());var answersMap=messages.Where(m=>Text(m,"emisor")=="Emprendedor"&&Text(m,"pregunta_id")!="").GroupBy(m=>Text(m,"pregunta_id")).ToDictionary(g=>g.Key,g=>g.OrderBy(m=>Text(m,"tiempo")).First());
  foreach(var product in catalog){var key=Id(product);var sellerAddress=addressesSeller.GetValueOrDefault(Text(product,"ownerRut"),[]).FirstOrDefault();product!["comuna"]=Text(communeMap.GetValueOrDefault(Text(sellerAddress,"comuna_id")),"nombre");var qRows=new JsonArray();foreach(var q in questionsMap.GetValueOrDefault(key,[])){var answer=answersMap.GetValueOrDefault(Id(q));qRows.Add(new JsonObject{["id"]=Id(q),["customerRut"]=Text(q,"cliente_id"),["user"]=Name(clientMap.GetValueOrDefault(Text(q,"cliente_id"))),["question"]=Text(q,"texto"),["createdAt"]=Text(q,"tiempo"),["date"]=Text(q,"tiempo"),["answer"]=answer==null?null:Text(answer,"texto"),["answerDate"]=Text(answer,"tiempo")});}data[Key("questions:"+key,"global")]=qRows;var reviewRows=new JsonArray(ratingsMap.GetValueOrDefault(key,[]).Select(q=>(JsonNode?)new JsonObject{["id"]=Id(q),["customerRut"]=Text(q,"cliente_id"),["author"]=Name(clientMap.GetValueOrDefault(Text(q,"cliente_id"))),["rating"]=Number(q,"puntaje"),["comment"]=Text(q,"comentario"),["date"]=Text(q,"fecha"),["createdAt"]=Text(q,"fecha"),["verified"]=true}).ToArray());data[Key("reviews:"+key,"global")]=reviewRows;product!["reviews"]=reviewRows.Count;product["rating"]=reviewRows.Count==0?null:reviewRows.Average(x=>(double)Number(x,"rating"));}
  var wishes=await Query(c,tx,"SELECT jsonb_build_object('type','Producto','item',producto_id,'rut',cliente_id)::text FROM public.desearp UNION ALL SELECT jsonb_build_object('type','Servicio','item',servicio_id,'rut',cliente_id)::text FROM public.desears",ct);
  var firstCatalog=catalog.GroupBy(x=>(Text(x,"tipo"),Text(x,"dbId"))).ToDictionary(g=>g.Key,g=>g.First());
  foreach(var group in wishes.GroupBy(x=>Text(x,"rut")))data[Key("wishlist",group.Key)]=new JsonArray(group.Select(w=>firstCatalog.GetValueOrDefault((Text(w,"type"),Text(w,"item")))?.DeepClone()).Where(x=>x!=null).ToArray());

 }
 public static string Name(JsonNode? person)=>person==null?"":(Text(person,"nombre")+" "+Text(person,"apellido")).Trim();
 public static string UiStatus(string status)=>status switch{"En Preparación"=>"En preparación","Despachado"=>"Enviado","Cancelada"=>"Cancelado",_=>status};
 public static string DbStatus(string status)=>status switch{"En preparación"=>"En Preparación","Enviado"=>"Despachado","Cancelado"=>"Cancelada",_=>status};
}
